SELECT  FROM im_channel_audit_log
 WHERE guild_kind = #{guildKind} AND guild_id = #{guildId}
 AND id < #{beforeId}
 ORDER BY id DESC
 LIMIT #{limit}

SELECT  FROM im_channel_audit_log
 WHERE guild_kind = #{guildKind} AND guild_id = #{guildId} AND id > #{afterId}
 ORDER BY id
 LIMIT #{limit}
